    public static boolean validId(String id){return id!=null&&id.matches("[a-f0-9]{32}");}
    public static boolean isCatalogUrl(String url,String catalogBase){
        if(!BASE_URL.equals(catalogBase)||url==null)return false;
        try {
            URI u=new URI(url);String path=u.getRawPath();
            if(!"https".equals(u.getScheme())||!"cintiabot.todosobreall.tech".equals(u.getHost())||u.getPort()!=-1||u.getRawUserInfo()!=null||u.getRawFragment()!=null)return false;
            String base="/api/public/community-themes";
            if(path.equals(base))return u.getRawQuery()==null||u.getRawQuery().matches("limit=20(&cursor=[A-Za-z0-9_-]{1,256})?");
            return u.getRawQuery()==null&&path.startsWith(base+"/")&&validId(path.substring(base.length()+1));
        }catch(Exception e){return false;}
    }
    public static byte[] canonical(Map<String,String> colors){
        if(colors==null||colors.isEmpty()||colors.size()>KEYS.size())throw new IllegalArgumentException("Colors");
        StringBuilder out=new StringBuilder();
        for(Map.Entry<String,String> e:new TreeMap<>(colors).entrySet()){
            if(!KEYS.contains(e.getKey())||e.getValue()==null||!e.getValue().matches("#[fF]{2}[a-fA-F0-9]{6}"))throw new IllegalArgumentException("Color key/value");
            out.append(e.getKey()).append('=').append((int)Long.parseLong(e.getValue().substring(1),16)).append('\n');
        }
        byte[] bytes=out.toString().getBytes(StandardCharsets.UTF_8);
        if(bytes.length>MAX_BYTES)throw new IllegalArgumentException("Theme size");return bytes;
    }
    public static boolean verifies(byte[] data,long size,String hash){
        if(data==null||data.length!=size||hash==null||!hash.matches("[a-f0-9]{64}"))return false;
        try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(data);StringBuilder value=new StringBuilder();for(byte b:digest)value.append(String.format(Locale.ROOT,"%02x",b&255));return MessageDigest.isEqual(value.toString().getBytes(StandardCharsets.US_ASCII),hash.getBytes(StandardCharsets.US_ASCII));}catch(Exception e){return false;}
    }
    public static String telegramUrl(String slug){
        if(slug==null||!slug.matches("[A-Za-z0-9_-]{1,128}"))throw new IllegalArgumentException("Theme slug");
        return "https://t.me/addtheme/"+slug;
    }
